  (* [comment removed for export] *)
  Definition hz_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LB : list block) (LF : list fframe) (N lo B shi : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : as_St H) (LB' : list block) (XS : list (Z * Z)),
      as_VIS H s' (cfg_ms c) = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                  F (ret_pc ra) fc None m' (seg_rom asegs)
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
      /\ rw_cells asegs m' (errno_addr tp) [C4 errv'] /\ as_rauxv_ok H m' B
      /\ as_RHEAP H s' LB' m' /\ Permutation LB' LB
      /\ Forall (fs_scratch H LF) XS
      /\ xpres H LB (bv_unsigned sp) ([(AXH_LO, AXH_HI); (AERRNO, AERRNO + 4)]%Z ++ XS) m m'
      /\ AHStat FT m'
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
      /\ as_AL H s' >= as_AL H s - hz_afuzz_cost N.

  Theorem afuzz_core :
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (msF : machine_state) (m : mem) (mo : Model)
           (s : as_St H) (LB : list block) (LF : list fframe) (CH : list (Z * Z)) (D N lo B shi : Z) (ds : list byte) (errv can : word),
      as_VIS H s msF = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                          F (Z_to_bv 64 P_AFUZZ_ENTRY) fc None m (seg_rom asegs) ->
      a0 = Z_to_bv 64 D -> a1 = Z_to_bv 64 N ->
      bytes_at asegs m D ds -> Z.of_nat (length ds) = N -> N < 2^26 -> D mod 16 = 0 ->
      (1 <= N -> exists pD, In (pD, D, N) LB) -> (N = 0 -> D = AFUZZ_EMPTY) ->
      as_RHEAP H s LB m -> as_AKREL H s (mkCfg msF mo) ->
      lb_bytes LB + AFUZZ_LIVE <= as_LIVE_MAX H -> Z.of_nat (length LB) + AFUZZ_CNT <= as_LIVE_CNT_MAX H ->
      as_rauxv_ok H m B -> bv_unsigned sp <= B -> B < 2^64 ->
      bv_unsigned sp mod 16 = 0 ->
      stk asegs m lo (bv_unsigned sp) -> aceil <= lo -> lo <= bv_unsigned sp - AFUZZ_STACK ->
      bv_unsigned sp <= 0x7fffffffffff ->
      rw_cells asegs m (errno_addr tp) [C4 errv] -> mem_inv asegs m -> tp = Z_to_bv 64 ATP ->
      AXImg m -> bytes_at asegs m ACANARY (word_to_le_bytes 8 can) -> AHStat FT m ->
      bv_unsigned ra mod 2 = 0 ->
      F = bvmap_empty -> fc = Z_to_bv 32 0 ->
      ACONST m ->
      (1 <= N -> addressable m D N) ->
      as_RFS H LF m -> (length LF + AFUZZ_FRAMES <= AFS7_MAXLIVE)%nat ->
      stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
      as_chain H m (bv_unsigned s0) CH -> pf_ok (as_TR H) APF_a3980 (bv_unsigned ra) CH ->
      (forall fp' ra', In (fp', ra') CH -> bv_unsigned sp + 16 <= fp') ->
      afuzz_tr_ok H ->
      hz_afuzz_cost N <= as_AL H s ->
      as_SR H (hz_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF N lo B shi m mo) (mkCfg msF mo).
  Proof.
    intros until can. intros VIS A0 A1 SRC LEN NMAX DAL INB DEMP HP KREL BUD BUDC AUX SPB BHI SPAL ST CEIL LO SP47 ERR MI TP XI CAN HSm RAE FZ1 FZ2 AC ADN RF LF7 SK SHI
           CHN PF CHB _ COST.
    subst a0 a1 tp.
    pose proof (ah_costs H HH) as (CM0 & CMM & CF0 & CFM & CMS & CFS).
    assert (N0 : 0 <= N) by (clear - LEN; lia).
    assert (DR : 0 <= D /\ D + N <= 2^64).
    { destruct (Z.eq_dec N 0) as [E|NE].
      - rewrite (DEMP E), E. unfold AFUZZ_EMPTY. clear; lia.
      - destruct (INB ltac:(clear - NE N0; lia)) as [pD IN]. pose proof (ah_blocks H HH _ _ _ _ HP IN) as (K1 & _ & _ & _ & K5 & _). cbn [blk_addr blk_size fst snd] in K1, K5.
        pose proof aceil_facts as (AF1 & _). clear - K1 K5 AF1. lia. }
    assert (PU : hz_pure H sp ra D N lo B shi LB LF).
    { unfold hz_pure. unfold AFUZZ_FRAMES, AFS7_MAXLIVE in LF7. unfold AFUZZ_FRAMES, AFS_MAXLIVE.
      repeat match goal with |- _ /\ _ => split end; try assumption; try (clear - N0 NMAX DR LF7 SHI LO; lia). }
    pose proof (hz_cost_fit N N0) as FIT.
    set (MA := hz_MA N) in *.
    assert (MA0 : 0 <= MA) by (pose proof (hz_MA_val N) as MV; clear - MV N0; lia).
    assert (POT : hz_pot H N LB MA).
    { unfold hz_pot. pose proof (hz_MA_val N) as MV. unfold AFUZZ_LIVE in BUD. unfold AFUZZ_CNT in BUDC.
      assert (PHV : sro_phi0 N = 7 * N + 271564) by (unfold sro_phi0, CAPMAX; clear; lia). unfold X8_pst.KB.
      split; [clear - BUD PHV NMAX N0; lia|]. split; [clear - BUDC; lia|]. split; [clear - NMAX; lia|]. subst MA. unfold hz_MA. clear. lia. }
    assert (LAD : hz_cost6 H MA N <= hz_cost7 H MA N /\ hz_cost7 H MA N <= hz_cost9 H MA N /\ hz_cost9 H MA N <= hz_cost10 H MA N).
    { unfold hz_cost10, hz_cost9, hz_cost8, hz_cost7. pose proof (CF0 NEWSZ_CFG ltac:(clear; unfold NEWSZ_CFG; lia)). pose proof (CF0 NEWSZ_REG ltac:(clear; unfold NEWSZ_REG; lia)).
      pose proof (CF0 SZ_ALLOCIMPL ltac:(clear; unfold SZ_ALLOCIMPL; lia)). pose proof (CF0 (CAPMAX N) ltac:(unfold CAPMAX; clear - N0; lia)). clear - H0 H1 H2 H3. lia. }
    destruct LAD as (L7 & L9 & L10).
    (* [comment removed for export] *)
    assert (TRK1 : trace_ok (as_TR H) APC0_FREE (P_HZ_RET_SDT :: bv_unsigned ra :: map snd CH)) by exact (pf_ok_site _ _ _ _ _ _ PF ltac:(do 2 right; left; reflexivity)).
    assert (TRK2 : trace_ok (as_TR H) APC0_FREE (P_HZ_RET_ADS :: bv_unsigned ra :: map snd CH)) by exact (pf_ok_site _ _ _ _ _ _ PF ltac:(do 6 right; left; reflexivity)).
